@Test
void testDownstreamResolution() throws Exception {
    final RequestRouter<Long> requestRouter = RequestRouter.<Long>builder(UriPatternType.URI_PATTERN).addRoute(new URIAuthority("somehost", 80), "/*", 1L).addRoute(new URIAuthority("someotherhost", 80), "/*", 10L).resolveAuthority((scheme, authority) -> authority).downstream((request, context) -> -1L).build();
    final HttpCoreContext context = HttpCoreContext.create();
    Assertions.assertEquals(-1L, requestRouter.resolve(BasicRequestBuilder.get("http://somehost/blah").build(), context));
    Assertions.assertEquals(10L, requestRouter.resolve(BasicRequestBuilder.get("http://someotherhost:80/blah").build(), context));
    Assertions.assertEquals(1L, requestRouter.resolve(BasicRequestBuilder.get("http://somehost:80/blah").build(), context));
    Assertions.assertEquals(-1L, requestRouter.resolve(BasicRequestBuilder.get("http://somehost:8080/blah").build(), context));
    Assertions.assertEquals(-1L, requestRouter.resolve(BasicRequestBuilder.get("/blah").build(), context));
    Assertions.assertEquals(-1L, requestRouter.resolve(BasicRequestBuilder.get("http://somehere.in.pampa/stuff").build(), context));
}

