    final List<NameValuePair> result = EntityUtils.parse(entity);
    Assertions.assertEquals(2, result.size());
    assertNameValuePair(result.get(0), "russian", ru_hello);
    assertNameValuePair(result.get(1), "swiss", ch_hello);
}

