    cb.addFirst(null);
    cb.addAllFirst((List<HttpRequestInterceptor>) null);
    cb.addLast(i4);
    cb.addLast(null);
    cb.addAllLast(i5);
    cb.addAllLast((List<HttpRequestInterceptor>) null);
    cb.addFirst(i1);
    cb.addAllLast(i3, i4, i5);
    final LinkedList<HttpRequestInterceptor> list = cb.build();
