    Assertions.assertEquals("http://www.example.com/%3C", new URIBuilder("http://www.example.com/%3c").optimize().build().toASCIIString());
    Assertions.assertEquals("http://www.example.com/", new URIBuilder("HTTP://www.EXAMPLE.com/").optimize().build().toASCIIString());
    Assertions.assertEquals("http://www.example.com/a%2F", new URIBuilder("http://www.example.com/a%2f").optimize().build().toASCIIString());
