    Assertions.assertEquals("http://www.example.com/%23?q=%26", new URIBuilder("http://www.example.com/%23?q=%26").optimize().build().toASCIIString());
    Assertions.assertEquals("http://www.example.com/blah-%28%20-blah-%20%26%20-blah-%20%29-blah/", new URIBuilder("http://www.example.com/blah-%28%20-blah-%20&%20-blah-%20)-blah/").optimize().build().toASCIIString());
