    }
    buffer.clear();
    Assertions.assertEquals(16, buffer.capacity());
    Assertions.assertEquals(0, buffer.length());
    Assertions.assertTrue(buffer.isEmpty());
    Assertions.assertFalse(buffer.isFull());
}

