}

@Test
void testHeaderSizeLimit() throws Exception {
    final HPackEncoder encoder = new HPackEncoder(Integer.MAX_VALUE, StandardCharsets.US_ASCII);
    final HPackDecoder decoder = new HPackDecoder(Integer.MAX_VALUE, StandardCharsets.US_ASCII);
    final ByteArrayBuffer buf = new ByteArrayBuffer(128);
    encoder.encodeHeaders(buf, Arrays.asList(new BasicHeader("regular-header", "blah"), new BasicHeader("big-f-header", "12345678901234567890123456789012345678901234567890" + "123456789012345678901234567890123456789012345678901234567890")), false);
    assertThat(decoder.decodeHeaders(wrap(buf)).size(), CoreMatchers.equalTo(2));
    decoder.setMaxListSize(1000000);
    assertThat(decoder.decodeHeaders(wrap(buf)).size(), CoreMatchers.equalTo(2));
    decoder.setMaxListSize(200);
    Assertions.assertThrows(HeaderListConstraintException.class, () -> decoder.decodeHeaders(wrap(buf)));
}

