    client.start();
    final Future<ClientSessionEndpoint> connectFuture = client.connect(target, TIMEOUT);
    final ClientSessionEndpoint streamEndpoint = connectFuture.get();
    final int n = 10;
    final CountDownLatch latch = new CountDownLatch(n);
    final AtomicInteger count = new AtomicInteger(0);
    for (int i = 0; i < n; i++) {
        final BasicHttpRequest request = BasicRequestBuilder.get().setHttpHost(target).setPath("/hello").build();
        streamEndpoint.execute(new BasicRequestProducer(request, null), new BasicResponseConsumer<>(new StringAsyncEntityConsumer()), null);
        streamEndpoint.execute(new PingCommand(new BasicPingHandler(result -> {
            if (result) {
                count.incrementAndGet();
            }
            latch.countDown();
        })), Command.Priority.NORMAL);
    }
    Assertions.assertTrue(latch.await(TIMEOUT.getDuration(), TIMEOUT.getTimeUnit()));
    Assertions.assertEquals(n, count.get());
}

