    assertThat(body1, CoreMatchers.equalTo("some stuff"));
    // Connect using plain HTTP scheme
    final Future<AsyncClientEndpoint> endpointFuture = requester.connect(new HttpHost(URIScheme.HTTP.id, "localhost", address.getPort()), TIMEOUT);
    final AsyncClientEndpoint clientEndpoint = endpointFuture.get(TIMEOUT.getDuration(), TIMEOUT.getTimeUnit());
    Assertions.assertInstanceOf(TlsUpgradeCapable.class, clientEndpoint);
    // Upgrade to TLS
    final BasicFuture<TlsDetails> tlsFuture = new BasicFuture<>(null);
    ((TlsUpgradeCapable) clientEndpoint).tlsUpgrade(target, new CompletingFutureContribution<>(tlsFuture, ProtocolIOSession::getTlsDetails));
    final TlsDetails tlsDetails = tlsFuture.get(TIMEOUT.getDuration(), TIMEOUT.getTimeUnit());
    Assertions.assertNotNull(tlsDetails);
    // Execute request over HTTPS
    final Future<Message<HttpResponse, String>> resultFuture2 = clientEndpoint.execute(new BasicRequestProducer(Method.POST, target, "/stuff", new StringAsyncEntityProducer("some stuff", ContentType.TEXT_PLAIN)), new BasicResponseConsumer<>(new StringAsyncEntityConsumer()), null);
    final Message<HttpResponse, String> message2 = resultFuture2.get(TIMEOUT.getDuration(), TIMEOUT.getTimeUnit());
    assertThat(message2, CoreMatchers.notNullValue());
    final HttpResponse response2 = message2.getHead();
    assertThat(response2.getCode(), CoreMatchers.equalTo(HttpStatus.SC_OK));
    final String body2 = message2.getBody();
    assertThat(body2, CoreMatchers.equalTo("some stuff"));
}

@Test
void testSimpleRequest() throws Exception {
    final InetSocketAddress address = startServer();
    final HttpAsyncRequester requester = clientResource.start();
    final byte[] input = new byte[1024];
    RANDOM.nextBytes(input);
    final Publisher<ByteBuffer> publisher = Flowable.just(ByteBuffer.wrap(input));
    final ReactiveEntityProducer producer = new ReactiveEntityProducer(publisher, input.length, null, null);
    final BasicRequestProducer request = getRequestProducer(address, producer);
    final ReactiveResponseConsumer consumer = new ReactiveResponseConsumer();
    requester.execute(request, consumer, SOCKET_TIMEOUT, null);
    final Message<HttpResponse, Publisher<ByteBuffer>> response = consumer.getResponseFuture().get(RESULT_TIMEOUT.getDuration(), RESULT_TIMEOUT.getTimeUnit());
    final ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
    final WritableByteChannel writableByteChannel = Channels.newChannel(byteArrayOutputStream);
    for (final ByteBuffer byteBuffer : Observable.fromPublisher(response.getBody()).toList().blockingGet()) {
        writableByteChannel.write(byteBuffer);
    }
    writableByteChannel.close();
    final byte[] output = byteArrayOutputStream.toByteArray();
    Assertions.assertArrayEquals(input, output);
}

